package com.quincaisoft.branch.infrastructure;import jakarta.persistence.*;import java.util.*;@Entity @Table(name="branch") @IdClass(BranchEntity.Key.class) public class BranchEntity {public record Key(UUID tenantId,UUID id,UUID companyId) implements java.io.Serializable{}@Id @Column(name="tenant_id")public UUID tenantId;@Id public UUID id;public String name;@Id @Column(name="company_id")public UUID companyId;public String timezone;}